import { ConflictError, ValidationError } from "./errors";

export const TASK_STATUSES = ["todo", "in progress", "done"] as const;
export type TaskStatus = (typeof TASK_STATUSES)[number];

export function isTaskStatus(value: unknown): value is TaskStatus {
  return typeof value === "string" && (TASK_STATUSES as readonly string[]).includes(value);
}

export interface Task {
  readonly id: string;
  readonly projectId: string;
  readonly title: string;
  readonly description: string;
  readonly dueDate?: Date;
  readonly status: TaskStatus;
  readonly assigneeId?: string;
}

export interface NewTaskProps {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date;
  status?: TaskStatus;
}

export function createTask(props: NewTaskProps): Task {
  if (typeof props.title !== "string" || props.title.trim() === "") {
    throw new ValidationError("Task title is required");
  }
  if (typeof props.description !== "string") {
    throw new ValidationError("Task description must be a string");
  }
  if (props.dueDate !== undefined && Number.isNaN(props.dueDate.getTime())) {
    throw new ValidationError("Task due date is invalid");
  }
  const status = props.status ?? "todo";
  if (!isTaskStatus(status)) {
    throw new ValidationError("Task status must be one of: todo, in progress, done");
  }
  return {
    id: props.id,
    projectId: props.projectId,
    title: props.title.trim(),
    description: props.description,
    dueDate: props.dueDate,
    status,
  };
}

export function assignTask(task: Task, assigneeId: string): Task {
  return { ...task, assigneeId };
}

export function markTaskDone(task: Task): Task {
  if (task.status === "done") {
    throw new ConflictError("Task is already done");
  }
  return { ...task, status: "done" };
}

export interface TaskFilter {
  status?: TaskStatus;
  assigneeId?: string;
}

export interface TaskRepository {
  save(task: Task): void;
  findById(id: string): Task | undefined;
  findByProject(projectId: string, filter: TaskFilter): Task[];
}

